method greatest_common_divisor(a: int, b: int) returns (gcd: int)
    // pre-conditions-start
    requires a != 0 || b != 0
    // pre-conditions-end
    // post-conditions-start
    ensures gcd != 0
    // post-conditions-end
{
    // impl-start
    var x := if a < 0 then -a else a;
    var y := if b < 0 then -b else b;

    if x == 0 {
        gcd := y;
        return;
    }
    if y == 0 {
        gcd := x;
        return;
    }

    while y > 0
        invariant x > 0
        invariant y >= 0
        decreases y
    {
        var temp := y;
        y := x % y;
        x := temp;
    }

    gcd := x;
    // impl-end
}

